﻿/**
 * Smart Refactor Tool
 *
 * Provides intelligent refactoring suggestions with code examples
 * Analyzes code patterns and suggests improvements
 * Target: 75-85% token reduction through suggestion summarization
 *
 * BABEL PORT (see code-analysis/index.ts's header "THE BLOCKER"): every
 * suggestion this tool generates comes from AST SHAPE (nesting depth,
 * operator counts, identifier text, literal repetition) or from
 * `SmartComplexityTool`'s own already-ported metrics -- never from resolved
 * type information -- so this is a faithful, no-capability-loss port to
 * `@babel/parser` + the manual `@babel/types`-`VISITOR_KEYS` walk in
 * ./babel-ast-utils.ts (see that file's header for why not `@babel/traverse`).
 * Same real behavior difference as smart-complexity.ts: `@babel/parser`
 * throws on malformed syntax instead of `ts.createSourceFile`'s silent
 * recovery.
 */

import { parse } from '@babel/parser';
import { existsSync, readFileSync } from 'fs';
import { join, isAbsolute } from 'path';
import { createHash } from 'crypto';
import { CacheEngine } from '../../core/cache-engine.js';
import { MetricsCollector } from '../../core/metrics.js';
import { TokenCounter } from '../../core/token-counter.js';
import {
  SmartComplexityTool,
  getSmartComplexityTool,
} from './smart-complexity.js';
// PATH RECONCILIATION (see src/optimizer/paths.ts's header): vendor's CLI
// default here was `join(homedir(), '.hypercontext', 'cache')` -- replaced
// with optiflow's own `~/.optiflow/optimizer/cache` convention.
import { getOptimizerCacheDbPath } from '../../paths.js';
import { type AnyNode, walk, locOf, textOf } from './babel-ast-utils.js';

export interface SmartRefactorOptions {
  filePath?: string;
  fileContent?: string;
  projectRoot?: string;
  refactorTypes?: Array<
    | 'extract-method'
    | 'simplify-conditional'
    | 'remove-duplication'
    | 'improve-naming'
    | 'reduce-complexity'
    | 'extract-constant'
  >;
  minComplexityForExtraction?: number;
  force?: boolean;
  maxCacheAge?: number;
}

export interface RefactorSuggestion {
  type: string;
  severity: 'info' | 'warning' | 'error';
  location: {
    line: number;
    column: number;
    endLine?: number;
    endColumn?: number;
  };
  message: string;
  suggestion: string;
  codeExample?: {
    before: string;
    after: string;
  };
  impact: {
    complexity?: number;
    readability?: 'low' | 'medium' | 'high';
    maintainability?: 'low' | 'medium' | 'high';
  };
}

export interface SmartRefactorResult {
  summary: {
    file: string;
    totalSuggestions: number;
    bySeverity: Record<string, number>;
    byType: Record<string, number>;
    estimatedImpact: 'low' | 'medium' | 'high';
    fromCache: boolean;
    duration: number;
  };
  suggestions: RefactorSuggestion[];
  metrics: {
    originalTokens: number;
    compactedTokens: number;
    reductionPercentage: number;
  };
}

export class SmartRefactorTool {
  private cache: CacheEngine;
  private metrics: MetricsCollector;
  private tokenCounter: TokenCounter;
  private cacheNamespace = 'smart_refactor';
  private projectRoot: string;
  private complexityTool: SmartComplexityTool;

  constructor(
    cache: CacheEngine,
    tokenCounter: TokenCounter,
    metrics: MetricsCollector,
    projectRoot?: string
  ) {
    this.cache = cache;
    this.tokenCounter = tokenCounter;
    this.metrics = metrics;
    this.projectRoot = projectRoot || process.cwd();
    this.complexityTool = getSmartComplexityTool(cache, tokenCounter, metrics);
  }

  async run(options: SmartRefactorOptions = {}): Promise<SmartRefactorResult> {
    const startTime = Date.now();
    const {
      filePath,
      fileContent,
      projectRoot = this.projectRoot,
      refactorTypes = [
        'extract-method',
        'simplify-conditional',
        'remove-duplication',
        'improve-naming',
        'reduce-complexity',
        'extract-constant',
      ],
      minComplexityForExtraction = 10,
      force = false,
      maxCacheAge = 300,
    } = options;

    if (!filePath && !fileContent) {
      throw new Error('Either filePath or fileContent must be provided');
    }

    // Read file content
    let content: string;
    let absolutePath: string | undefined;

    if (fileContent) {
      content = fileContent;
    } else if (filePath) {
      // An ABSOLUTE filePath must be used as given.
      // join(projectRoot, filePath) on an absolute path produces nonsense --
      // a project root with a drive letter glued onto it -- and the tool then
      // reports "File not found" for a file that is plainly there. Measured
      // live: every call with an absolute path failed exactly this way.
      absolutePath = isAbsolute(filePath)
        ? filePath
        : join(projectRoot, filePath);
      if (!existsSync(absolutePath)) {
        throw new Error(`File not found: ${absolutePath}`);
      }
      content = readFileSync(absolutePath, 'utf-8');
    } else {
      throw new Error('No content provided');
    }

    // Generate cache key
    const cacheKey = await this.generateCacheKey(
      content,
      refactorTypes,
      minComplexityForExtraction
    );

    // Check cache
    if (!force) {
      const cached = this.getCachedResult(cacheKey, maxCacheAge);
      if (cached) {
        this.metrics.record({
          operation: 'smart_refactor',
          duration: Date.now() - startTime,
          cacheHit: true,
          inputTokens: cached.metrics.originalTokens,
          cachedTokens: cached.metrics.compactedTokens,
          success: true,
        });
        return cached;
      }
    }

    // Parse TypeScript/JavaScript. See this file's top-of-file BABEL PORT
    // comment: unlike ts.createSourceFile, this throws on malformed syntax
    // rather than silently recovering.
    const ast = parse(content, {
      sourceType: 'module',
      plugins: ['jsx', 'typescript'],
    });
    const program = ast.program as unknown as AnyNode;

    // Get complexity metrics
    const complexityResult = await this.complexityTool.run({
      fileContent: content,
      projectRoot,
      force: true,
    });

    // Analyze and generate suggestions
    const suggestions: RefactorSuggestion[] = [];

    for (const type of refactorTypes) {
      switch (type) {
        case 'extract-method':
          suggestions.push(
            ...this.suggestExtractMethod(
              complexityResult,
              minComplexityForExtraction
            )
          );
          break;
        case 'simplify-conditional':
          suggestions.push(...this.suggestSimplifyConditional(program));
          break;
        case 'remove-duplication':
          suggestions.push(
            ...this.suggestRemoveDuplication(program, content)
          );
          break;
        case 'improve-naming':
          suggestions.push(...this.suggestImproveNaming(program));
          break;
        case 'reduce-complexity':
          suggestions.push(...this.suggestReduceComplexity(complexityResult));
          break;
        case 'extract-constant':
          suggestions.push(...this.suggestExtractConstant(program));
          break;
      }
    }

    // Calculate summary statistics
    const bySeverity: Record<string, number> = {
      info: suggestions.filter((s) => s.severity === 'info').length,
      warning: suggestions.filter((s) => s.severity === 'warning').length,
      error: suggestions.filter((s) => s.severity === 'error').length,
    };

    const byType: Record<string, number> = {};
    for (const suggestion of suggestions) {
      byType[suggestion.type] = (byType[suggestion.type] || 0) + 1;
    }

    const estimatedImpact = this.calculateEstimatedImpact(suggestions);

    // Build result
    const result: SmartRefactorResult = {
      summary: {
        file: filePath || 'anonymous',
        totalSuggestions: suggestions.length,
        bySeverity,
        byType,
        estimatedImpact,
        fromCache: false,
        duration: Date.now() - startTime,
      },
      suggestions,
      metrics: {
        originalTokens: 0,
        compactedTokens: 0,
        reductionPercentage: 0,
      },
    };

    // Calculate token metrics
    const originalText = JSON.stringify(result, null, 2);
    const compactText = this.compactResult(result);
    result.metrics.originalTokens =
      this.tokenCounter.count(originalText).tokens;
    result.metrics.compactedTokens =
      this.tokenCounter.count(compactText).tokens;
    result.metrics.reductionPercentage =
      ((result.metrics.originalTokens - result.metrics.compactedTokens) /
        result.metrics.originalTokens) *
      100;

    // Cache result
    this.cacheResult(cacheKey, result);

    // Record metrics
    this.metrics.record({
      operation: 'smart_refactor',
      duration: Date.now() - startTime,
      cacheHit: false,
      inputTokens: result.metrics.originalTokens,
      cachedTokens: result.metrics.compactedTokens,
      success: true,
    });

    return result;
  }

  private suggestExtractMethod(
    complexityResult: any,
    minComplexity: number
  ): RefactorSuggestion[] {
    const suggestions: RefactorSuggestion[] = [];

    // Find complex functions
    const complexFunctions = complexityResult.functions.filter(
      (f: any) => f.complexity.cyclomatic >= minComplexity
    );

    for (const func of complexFunctions) {
      const location = func.location;
      suggestions.push({
        type: 'extract-method',
        severity: func.complexity.cyclomatic > 20 ? 'error' : 'warning',
        location,
        message: `Function '${func.name}' has high complexity (${func.complexity.cyclomatic}). Consider extracting smaller methods.`,
        suggestion: `Break down '${func.name}' into smaller, focused functions with single responsibilities.`,
        impact: {
          complexity: func.complexity.cyclomatic - minComplexity,
          readability: 'high',
          maintainability: 'high',
        },
      });
    }

    return suggestions;
  }

  private suggestSimplifyConditional(program: AnyNode): RefactorSuggestion[] {
    const suggestions: RefactorSuggestion[] = [];

    walk(program, (node) => {
      // Nested if statements
      if (node.type === 'IfStatement') {
        const nestedIfs = this.countNestedIfs(node);
        if (nestedIfs > 2) {
          const pos = locOf(node);
          suggestions.push({
            type: 'simplify-conditional',
            severity: 'warning',
            location: pos,
            message: `Deeply nested if statements (${nestedIfs} levels). Consider using early returns or guard clauses.`,
            suggestion:
              'Use early returns or extract conditions into well-named variables.',
            codeExample: {
              before:
                'if (a) {\n  if (b) {\n    if (c) {\n      doSomething();\n    }\n  }\n}',
              after:
                'if (!a) return;\nif (!b) return;\nif (!c) return;\ndoSomething();',
            },
            impact: {
              readability: 'high',
              maintainability: 'high',
            },
          });
        }
      }

      // Complex boolean expressions. TS's classic API models &&/|| as
      // BinaryExpression; Babel gives them a separate LogicalExpression
      // node type instead.
      if (node.type === 'LogicalExpression') {
        const complexity = this.countLogicalOperators(node);
        if (complexity > 3) {
          const pos = locOf(node);
          suggestions.push({
            type: 'simplify-conditional',
            severity: 'warning',
            location: pos,
            message: `Complex boolean expression with ${complexity} logical operators. Consider extracting into well-named variables.`,
            suggestion:
              'Extract complex conditions into descriptively named boolean variables.',
            codeExample: {
              before: 'if (a && b || c && d || e && f) { }',
              after:
                'const hasValidInput = a && b;\nconst hasSpecialCase = c && d;\nconst hasOverride = e && f;\nif (hasValidInput || hasSpecialCase || hasOverride) { }',
            },
            impact: {
              readability: 'high',
              maintainability: 'medium',
            },
          });
        }
      }
    });

    return suggestions;
  }

  private suggestRemoveDuplication(
    program: AnyNode,
    content: string
  ): RefactorSuggestion[] {
    const suggestions: RefactorSuggestion[] = [];
    const codeBlocks = new Map<
      string,
      Array<{ location: { line: number; column: number }; text: string }>
    >();

    walk(program, (node) => {
      // Look for duplicate blocks (functions, if statements, etc.). Babel
      // splits TS's single `MethodDeclaration` into `ClassMethod`/
      // `ObjectMethod` -- see smart-complexity.ts's identical note.
      if (
        node.type === 'FunctionDeclaration' ||
        node.type === 'ClassMethod' ||
        node.type === 'ObjectMethod' ||
        node.type === 'IfStatement' ||
        node.type === 'BlockStatement'
      ) {
        const text = textOf(node, content).trim();
        if (text.length > 100) {
          // Only consider substantial blocks
          const hash = createHash('md5').update(text).digest('hex');
          if (!codeBlocks.has(hash)) {
            codeBlocks.set(hash, []);
          }
          codeBlocks.get(hash)!.push({
            location: locOf(node),
            text,
          });
        }
      }
    });

    // Report duplicates
    for (const [_hash, blocks] of codeBlocks) {
      if (blocks.length > 1) {
        const firstBlock = blocks[0];
        suggestions.push({
          type: 'remove-duplication',
          severity: 'warning',
          location: firstBlock.location,
          message: `Found ${blocks.length} duplicate or very similar code blocks.`,
          suggestion:
            'Extract common logic into a reusable function or utility.',
          impact: {
            maintainability: 'high',
            readability: 'medium',
          },
        });
      }
    }

    return suggestions;
  }

  private suggestImproveNaming(program: AnyNode): RefactorSuggestion[] {
    const suggestions: RefactorSuggestion[] = [];

    walk(program, (node) => {
      if (node.type === 'Identifier') {
        const name = node.name as string;

        // Check for single-letter variables (except common ones like i, j, k in loops)
        if (
          name.length === 1 &&
          !['i', 'j', 'k', 'x', 'y', 'z'].includes(name)
        ) {
          const pos = locOf(node);
          suggestions.push({
            type: 'improve-naming',
            severity: 'info',
            location: pos,
            message: `Single-letter variable '${name}' is not descriptive.`,
            suggestion:
              "Use a descriptive name that explains the variable's purpose.",
            impact: {
              readability: 'medium',
              maintainability: 'low',
            },
          });
        }

        // Check for generic names
        const genericNames = [
          'data',
          'temp',
          'tmp',
          'foo',
          'bar',
          'test',
          'obj',
          'arr',
        ];
        if (genericNames.includes(name.toLowerCase())) {
          const pos = locOf(node);
          suggestions.push({
            type: 'improve-naming',
            severity: 'info',
            location: pos,
            message: `Generic variable name '${name}' lacks clarity.`,
            suggestion:
              'Use a more specific name that describes what this variable contains or represents.',
            impact: {
              readability: 'medium',
              maintainability: 'low',
            },
          });
        }

        // Check for inconsistent naming conventions
        if (name.includes('_') && name.includes(name.toUpperCase())) {
          // Mix of snake_case and SCREAMING_CASE
          const pos = locOf(node);
          suggestions.push({
            type: 'improve-naming',
            severity: 'info',
            location: pos,
            message: `Inconsistent naming convention in '${name}'.`,
            suggestion:
              'Use consistent naming: camelCase for variables/functions, PascalCase for classes, SCREAMING_CASE for constants.',
            impact: {
              readability: 'low',
              maintainability: 'low',
            },
          });
        }
      }
    });

    return suggestions;
  }

  private suggestReduceComplexity(complexityResult: any): RefactorSuggestion[] {
    const suggestions: RefactorSuggestion[] = [];

    // Check for high cognitive complexity
    for (const func of complexityResult.functions) {
      if (func.complexity.cognitive > 15) {
        const location = func.location;
        suggestions.push({
          type: 'reduce-complexity',
          severity: func.complexity.cognitive > 25 ? 'error' : 'warning',
          location,
          message: `Function '${func.name}' has high cognitive complexity (${func.complexity.cognitive}).`,
          suggestion:
            'Reduce nesting, extract helper functions, and simplify control flow.',
          codeExample: {
            before: 'Complex nested logic with multiple conditions',
            after:
              'Flat structure with early returns and extracted helper functions',
          },
          impact: {
            complexity: func.complexity.cognitive - 15,
            readability: 'high',
            maintainability: 'high',
          },
        });
      }
    }

    return suggestions;
  }

  private suggestExtractConstant(program: AnyNode): RefactorSuggestion[] {
    const suggestions: RefactorSuggestion[] = [];
    const magicNumbers = new Map<string, number>();

    walk(program, (node) => {
      if (node.type === 'NumericLiteral') {
        // Raw source text (not the parsed numeric value), matching
        // ts.NumericLiteral.text -- see smart-complexity.ts's identical
        // Halstead-operand note for why.
        const value = String(node.extra?.raw ?? node.value);
        // Skip common non-magic numbers
        if (!['0', '1', '-1', '2'].includes(value)) {
          magicNumbers.set(value, (magicNumbers.get(value) || 0) + 1);
        }
      }

      if (node.type === 'StringLiteral') {
        const value = node.value as string;
        // Look for repeated string literals that might be constants
        if (value.length > 5) {
          // Skip very short strings
          magicNumbers.set(value, (magicNumbers.get(value) || 0) + 1);
        }
      }
    });

    // Report values that appear multiple times
    for (const [value, count] of magicNumbers) {
      if (count > 2) {
        suggestions.push({
          type: 'extract-constant',
          severity: 'info',
          location: { line: 1, column: 0 },
          message: `Value '${value}' appears ${count} times. Consider extracting as a named constant.`,
          suggestion: `Extract '${value}' into a descriptively named constant to improve maintainability.`,
          codeExample: {
            before: `const x = ${value};\nconst y = ${value};`,
            after: `const DESCRIPTIVE_NAME = ${value};\nconst x = DESCRIPTIVE_NAME;\nconst y = DESCRIPTIVE_NAME;`,
          },
          impact: {
            maintainability: 'medium',
            readability: 'low',
          },
        });
      }
    }

    return suggestions;
  }

  /** `node.thenStatement` -> Babel's `node.consequent`;
   * `ts.isBlock` -> Babel's `BlockStatement`. */
  private countNestedIfs(node: AnyNode, depth = 1): number {
    const consequent = node.consequent;
    if (consequent?.type === 'IfStatement') {
      return this.countNestedIfs(consequent, depth + 1);
    }
    if (consequent?.type === 'BlockStatement') {
      for (const statement of consequent.body) {
        if (statement.type === 'IfStatement') {
          return this.countNestedIfs(statement, depth + 1);
        }
      }
    }
    return depth;
  }

  /** TS's classic API models &&/|| as BinaryExpression; Babel's is a
   * dedicated LogicalExpression node type instead. */
  private countLogicalOperators(node: AnyNode): number {
    let count = 0;

    walk(node, (n) => {
      if (
        n.type === 'LogicalExpression' &&
        (n.operator === '&&' || n.operator === '||')
      ) {
        count++;
      }
    });

    return count;
  }

  private calculateEstimatedImpact(
    suggestions: RefactorSuggestion[]
  ): 'low' | 'medium' | 'high' {
    const highImpact = suggestions.filter(
      (s) =>
        s.impact.readability === 'high' || s.impact.maintainability === 'high'
    ).length;

    const errors = suggestions.filter((s) => s.severity === 'error').length;

    if (errors > 0 || highImpact > 5) return 'high';
    if (highImpact > 2) return 'medium';
    return 'low';
  }

  private compactResult(result: SmartRefactorResult): string {
    // Create compact summary for token efficiency
    const compact = {
      file: result.summary.file,
      total: result.summary.totalSuggestions,
      impact: result.summary.estimatedImpact,
      suggestions: result.suggestions.map((s) => ({
        t: s.type,
        s: s.severity,
        l: s.location.line,
        m: s.message.substring(0, 100),
      })),
    };

    return JSON.stringify(compact);
  }

  private async generateCacheKey(
    content: string,
    refactorTypes: string[],
    minComplexity: number
  ): Promise<string> {
    const hash = createHash('sha256');
    hash.update(this.cacheNamespace);
    hash.update(content);
    hash.update(JSON.stringify({ refactorTypes, minComplexity }));
    return `${this.cacheNamespace}:${hash.digest('hex')}`;
  }

  private getCachedResult(
    key: string,
    maxAge: number
  ): SmartRefactorResult | null {
    const cached = this.cache.get(key);
    if (!cached) return null;

    const result = JSON.parse(cached) as SmartRefactorResult & {
      cachedAt: number;
    };
    const age = (Date.now() - result.cachedAt) / 1000;

    if (age <= maxAge) {
      result.summary.fromCache = true;
      return result;
    }

    return null;
  }

  private cacheResult(key: string, output: SmartRefactorResult): void {
    const toCache = { ...output, cachedAt: Date.now() };
    const buffer = JSON.stringify(toCache);
    const tokensSaved =
      output.metrics.originalTokens - output.metrics.compactedTokens;
    this.cache.set(key, buffer, 300, tokensSaved);
  }
}

// Factory function for dependency injection
export function getSmartRefactorTool(
  cache: CacheEngine,
  tokenCounter: TokenCounter,
  metrics: MetricsCollector,
  projectRoot?: string
): SmartRefactorTool {
  return new SmartRefactorTool(cache, tokenCounter, metrics, projectRoot);
}

// Standalone function for CLI usage
export async function runSmartRefactor(
  options: SmartRefactorOptions
): Promise<SmartRefactorResult> {
  const cache = new CacheEngine(getOptimizerCacheDbPath());
  const tokenCounter = new TokenCounter();
  const metrics = new MetricsCollector();
  const tool = getSmartRefactorTool(
    cache,
    tokenCounter,
    metrics,
    options.projectRoot
  );
  return tool.run(options);
}

// MCP tool definition
export const SMART_REFACTOR_TOOL_DEFINITION = {
  name: 'smart_refactor',
  description:
    'Provides intelligent refactoring suggestions with code examples and impact analysis (75-85% token reduction)',
  inputSchema: {
    type: 'object',
    properties: {
      filePath: {
        type: 'string',
        description: 'File path to analyze (relative to project root)',
      },
      fileContent: {
        type: 'string',
        description: 'File content to analyze (alternative to filePath)',
      },
      projectRoot: {
        type: 'string',
        description: 'Project root directory',
      },
      refactorTypes: {
        type: 'array',
        description:
          'Types of refactoring suggestions to generate (default: all)',
        items: {
          type: 'string',
          enum: [
            'extract-method',
            'simplify-conditional',
            'remove-duplication',
            'improve-naming',
            'reduce-complexity',
            'extract-constant',
          ],
        },
      },
      minComplexityForExtraction: {
        type: 'number',
        description:
          'Minimum cyclomatic complexity to suggest extraction (default: 10)',
        default: 10,
      },
      force: {
        type: 'boolean',
        description: 'Force re-analysis (ignore cache)',
        default: false,
      },
      maxCacheAge: {
        type: 'number',
        description: 'Maximum cache age in seconds (default: 300)',
        default: 300,
      },
    },
  },
};
